/// <summary>
/// This class used for extension of PurchLineBackOrderListPage.
/// </summary>
[ExtensionOf(formDataSourceStr(PurchLineBackOrderListPage, PurchLineBackOrderWorkspace))]
internal final class METPurchLineBackOrderListPageFormDataSource_Extension
{
}

Method.Source:
/// <summary>
/// This is the COC method fro init method .
/// </summary>
public void init()
{
    next init();
    Args args = element.args();
    METItemInquiryHelper helper;
    FormRun callerForm = args.caller() as FormRun;

    if(element.args().parmObject())
    {
        helper = element.args().parmObject(); 
        ItemId                      itemIdFilter = helper.parmItemId();
        InventLocationId            inventLocationIdFilter = helper.parmInventLocationId();

        if (itemIdFilter || inventLocationIdFilter)
        {
            QueryBuildDataSource  qbds = this.queryBuildDataSource();
            qbds.addRange(fieldNum(PurchLineBackOrderWorkspace, ItemId)).value(queryValue(itemIdFilter));

            QueryBuildDataSource    qbds1 = qbds.addDataSource(tableNum(PurchTable));
            qbds1.joinMode(JoinMode::InnerJoin);
            qbds1.addLink(fieldNum(PurchLineBackOrderWorkspace, PurchId), fieldNum(PurchTable, PurchId));
            qbds1.addRange(fieldNum(PurchTable, InventLocationId)).value(queryValue(inventLocationIdFilter));
        }
    }
}
